  cover: "G:qBFEG4PanpWaCOD_a1N1tL436HQDo4mvZZz4OjWPMso9WamvqKyGfSo2Ce7NbUEPOTId9QCDuhlAMBIvkNQFuA", pages: ["G:obMwAQGMUi_A30I4hQvbHXxvT0RmmF8wtN7W9zctQN5YrKG0gdfSG8TGopDmYMYXlhmmsGAsZNxfpzK_zSX_"]
