    "2. Schritt: Aceto und Öl verrühren, würzen. Radiesli vierteln, Kerbel fein schneiden, in die Sauce geben. Spargeln im heissen Öl ca. 5 Min. rührbraten, salzen, mit den Radiesli mischen.",
