    "Milch, Rahm, Salz und Muskat gut verrühren, über die Kartoffeln giessen.",
    "Backen: ca. 50 Min. in der Mitte des Ofens.",
    "Rahm über den Gratin giessen.",
    "Fertig backen: ca. 20 Minuten.",
    "Ofen auf 180 Grad vorheizen.",
    "Knoblauch längs halbieren, Form damit ausreiben.",
    "Kartoffeln schälen, in dünne Scheiben hobeln, in eine Schüssel geben, würzen. Kartoffeln lagenweise in die vorbereitete Form schichten.",
