    "Gratin boulangère: 2 Zwiebeln in Ringe schneiden, zwischen den Kartoffeln verteilen. Statt Milch und Rahm 5.5 dl Gemüsebouillon verwenden. Alle Flüssigkeit auf einmal dazugiessen, sodass die Kartoffeln knapp bedeckt sind. Backen: ca. 35 Min. in der Mitte des auf 200 Grad vorgeheizten Ofens.",
