    "5 Minuten kochen",
    "Abgiessen, kalt abschrecken",
    "Edamame aus der Schote lösen",
    "Grapefruit samt weisser Haut schälen",
    "Grapefruitfilets aus den Zwischenhäutchen herauslösen und halbieren",
    "Austretenden Saft auffangen",
    "Avocados halbieren, Kern entfernen",
    "Fruchtfleisch aus der Schale lösen und in Schnitze schneiden",
    "Pfefferminze fein hacken",
    "Mit Grapefruitsaft, Olivenöl, Aceto balsamico und Honig mischen",
    "Mit Salz und Pfeffer abschmecken",
    "Jungsalat mit Edamame, Grapefruitfilets, Avocado und Dressing mischen und servieren"
