    "5 Minuten vor Schluss die kleinen, in Stücke geschnitten Stangenbroccoli beigeben.",
    "Giessen Sie die Pasta ab und stellen Sie dabei etwas Pastawasser zur Seite.",
    "Nun die Penne und den Broccoli mit den Tomaten mischen und etwas Pastawasser dazu geben.",
    "Anschliessend Basilikum untermischen und die Pasta mit zerkrümeltem Feta servieren."
